// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 ts, uint256 blk) public {
        ts = bound(ts, 1, 1e18);
        blk = bound(blk, 1, 1e18);
        vm.assume(ts != blk); // ensure timestamp differs from block number so the two writes diverge
        vm.roll(blk);
        vm.warp(ts);
        address caller = makeAddr("caller");
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok && c.pastBlockTime() == ts);
    }
}
